      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.8/open-walnut-0.6.8-darwin-arm64.tar.gz", using: :nounzip
      sha256 "413de9e7a8a6b90f1de6e38cbf99258c221ef560f0e40d5681c014884091176d"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.8/open-walnut-0.6.8-darwin-x64.tar.gz", using: :nounzip
      sha256 "23b94b29f2c0a61fbebcbbbb1a004bfbf1e420051d6c8bc5e4fdbcabad06abec"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.8/open-walnut-0.6.8-linux-arm64.tar.gz", using: :nounzip
      sha256 "c2ad062dc72144282090634cd6e577f45ddf987c2647f0aded18f26721192a6f"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.8/open-walnut-0.6.8-linux-x64.tar.gz", using: :nounzip
      sha256 "e1a667c46abea0c8c78833506bbad86baa5fe899bc3eb40ae47e67f513514052"
    end
  end

  def install
    libexec.install Dir["open-walnut-*.tar.gz"].first => "open-walnut.tar.gz"
    # Scripts, not links: the cleaner drops a link whose target is not there yet.
    bin.write_exec_script libexec/"app/bin/walnut", libexec/"app/bin/open-walnut"
  end

  # After Homebrew's install-name pass over the keg, which the archive must skip.
  # The packed copy goes once unpacked, so running these again changes nothing.
  post_install_steps do
    if_path_exists "open-walnut.tar.gz", base: :libexec do
      remove "app", base: :libexec, recursive: true
      mkdir_p "app", base: :libexec
      run "tar", args: ["-xzf", "{{libexec}}/open-walnut.tar.gz", "-C", "{{libexec}}/app", "--strip-components=1"],
                 writable_paths: ["app"], writable_base: :libexec
      remove "open-walnut.tar.gz", base: :libexec
    end
  end

  def caveats
    <<~EOS
      Start it with:
        walnut web
      Walnut keeps itself up to date: it installs new releases when it starts.
      Its sessions run Claude Code: https://claude.com/product/claude-code
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/walnut --version")
  end
end
